def _stem_word(word: str) -> str:
    if not word:
        return ""
    w = word.lower()
    exc = _EXC.get(w)
    if exc is not None:
        return exc
    wl = len(w)
    if wl > _AFF_MIN and w[0] in _PFXR:
        node = _PFXR
        bp = 0
        for ch in w:
            if ch not in node:
                break
            node, nd, op = node[ch]
            if nd <= wl:
                bp = op
        if bp:
            w = w[bp:]
            exc_pfx = _EXC.get(w)
            if exc_pfx is not None:
                return exc_pfx
    wl = len(w)
    t = _jget(w[-3:]) if wl >= 3 else None
    if t is not None:
        node, nd, best, rest = t
        if nd > wl:
            best = None
            for nd, op in rest:
                if nd <= wl:
                    best = op
                    break
        if node is not None:
            i = wl - 4
            while i >= 0:
                ch = w[i]
                if ch not in node:
                    break
                node, nd, op = node[ch]
                if nd <= wl:
                    best = op
                i -= 1
